// --- JSON REPAIR & CLEANING ---
const cleanJsonString = (jsonStr: string): string => {
    // Remove comments
    return jsonStr.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '').trim();
};

const repairTruncatedJSON = (jsonStr: string): string => {
    let repaired = jsonStr.trim();

    // 1. Fix trailing commas before closing brackets (common issue)
    repaired = repaired.replace(/,\s*([\]}])/g, '$1');

    // 2. Handle abrupt truncation at the end
    // If ends with comma, remove it
    if (repaired.endsWith(',')) {
        repaired = repaired.slice(0, -1);
    }

    // If ends with colon, append a placeholder value
    if (repaired.endsWith(':')) {
        repaired += ' "TRUNCATED"';
    }

    // Stack-based repair
    const stack = [];
    let inString = false;
    let escaped = false;

    for (let i = 0; i < repaired.length; i++) {
        const char = repaired[i];

        if (escaped) {
            escaped = false;
            continue;
        }

        if (char === '\\') {
            escaped = true;
            continue;
        }

        if (char === '"') {
            inString = !inString;
            continue;
        }

        if (!inString) {
            if (char === '{' || char === '[') {
                stack.push(char);
            } else if (char === '}' || char === ']') {
                if (stack.length > 0) {
                    const last = stack[stack.length - 1];
                    if ((char === '}' && last === '{') || (char === ']' && last === '[')) {
                        stack.pop();
                    }
                }
            }
        }
    }

    // Append missing closing brackets
    while (stack.length > 0) {
        const char = stack.pop();
        if (char === '{') repaired += '}';
        if (char === '[') repaired += ']';
    }

    return repaired;
};

